template <>
__device__ void fk<ppln::robots::FfwSg2>(
    const float* q,
    volatile float* sphere_pos, // 124 spheres x 16 robots x 3 coordinates (each column is a robot)
    float *T, // 16 robots x 2 x 4x4 transform matrix , column major
    const int tid
)
{
    // every 4 threads are responsible for one column of the transform matrix T
    // make_transform will calculate the necessary column of T_step needed for the thread
    const int col_ind = tid % 4;
    const int batch_ind = tid / 4;

    int T_offset = batch_ind * 2 * 16;
    float T_step_col[4]; // 4x1 column of the joint transform matrix for this thread
    float *T_base = T + T_offset; // 4x4 transform matrix for the batch
    
    #pragma unroll
    for (int i = 0; i < 2; ++i) {
        float *T_col_i = T_base + i * 16 + col_ind * 4;
        for (int r=0; r<4; r++) {
            T_col_i[r] = 0.0f;
        }
        T_col_i[col_ind] = 1.0f;
    }
    __syncthreads();

    int joint_to_sphere_ind = 0;

    for (int j = 0; j < FFW_SG2_JOINT_COUNT; ++j) {
        int i = ffw_sg2_dfs_order[j];
        float T_col_tmp[4];
        int parent_idx = ffw_sg2_joint_parents[i];
        int T_memory_idx_parent = ffw_sg2_T_memory_idx[parent_idx];
        int T_memory_idx = ffw_sg2_T_memory_idx[i];
        int q_idx = ffw_sg2_joint_id_to_dof[i];
        if (j > 0) {
            int ft_addr_start = i * 16;
            int joint_type = ffw_sg2_joint_types[i];

            if (joint_type <= FFW_SG2_Z_PRISM) {
                prism_fn(&ffw_sg2_fixed_transforms[ft_addr_start], q[q_idx], col_ind, T_step_col, joint_type);
            }
            else if (joint_type == FFW_SG2_X_ROT) {
                xrot_fn(&ffw_sg2_fixed_transforms[ft_addr_start], q[q_idx], col_ind, T_step_col);
            }
            else if (joint_type == FFW_SG2_Y_ROT) {
                yrot_fn(&ffw_sg2_fixed_transforms[ft_addr_start], q[q_idx], col_ind, T_step_col);
            }
            else if (joint_type == FFW_SG2_Z_ROT) {
                zrot_fn(&ffw_sg2_fixed_transforms[ft_addr_start], q[q_idx], col_ind, T_step_col);
            }
            
            for (int r=0; r<4; r++){
                T_col_tmp[r] = dot4_col(&T_base[T_memory_idx_parent*16 + r], T_step_col);
            }
            for (int r=0; r<4; r++){
                T_base[T_memory_idx*16 + col_ind*4 + r] = T_col_tmp[r];
            }
        }
        __syncwarp();
        while (ffw_sg2_flattened_joint_to_spheres[joint_to_sphere_ind] != -1) {
            int sphere_ind = ffw_sg2_flattened_joint_to_spheres[joint_to_sphere_ind];
            if (col_ind < 3) {
                // sphere sphere_ind, robot batch_ind (FFW_SG2_BATCH_SIZE robots), coord col_ind
                sphere_pos[sphere_ind * FFW_SG2_BATCH_SIZE * 3 + batch_ind * 3 + col_ind] = 
                    T_base[T_memory_idx*16 + col_ind] * ffw_sg2_spheres_array[sphere_ind].x +
                    T_base[T_memory_idx*16 + col_ind + M] * ffw_sg2_spheres_array[sphere_ind].y +
                    T_base[T_memory_idx*16 + col_ind + M*2] * ffw_sg2_spheres_array[sphere_ind].z +
                    T_base[T_memory_idx*16 + col_ind + M*3];
            }
            joint_to_sphere_ind++;
        }
        joint_to_sphere_ind++;
        __syncthreads();
    }
}

// 4 threads per discretized motion for self-collision check
template <>
__device__ bool self_collision_check<ppln::robots::FfwSg2>(volatile float* sphere_pos, volatile int* joint_in_collision, const int tid){
    const int thread_ind = tid % 4;
    const int batch_ind = tid / 4;
    bool has_collision = false;

    for (int i = thread_ind; i < FFW_SG2_SELF_CC_RANGE_COUNT; i += 4) {
        if (warp_any_active_mask(has_collision)) return false;
        int sphere_1_ind = ffw_sg2_self_cc_ranges[i][0];
        if (joint_in_collision[FFW_SG2_JOINT_FLAG_STRIDE * batch_ind + ffw_sg2_sphere_to_joint[sphere_1_ind]] == 0) continue;
        float sphere_1[3] = {
            sphere_pos[sphere_1_ind * FFW_SG2_BATCH_SIZE * 3 + batch_ind * 3 + 0],
            sphere_pos[sphere_1_ind * FFW_SG2_BATCH_SIZE * 3 + batch_ind * 3 + 1],
            sphere_pos[sphere_1_ind * FFW_SG2_BATCH_SIZE * 3 + batch_ind * 3 + 2]
        };
        for (int j = ffw_sg2_self_cc_ranges[i][1]; j <= ffw_sg2_self_cc_ranges[i][2]; j++) {
            float sphere_2[3] = {
                sphere_pos[j * FFW_SG2_BATCH_SIZE * 3 + batch_ind * 3 + 0],
                sphere_pos[j * FFW_SG2_BATCH_SIZE * 3 + batch_ind * 3 + 1],
                sphere_pos[j * FFW_SG2_BATCH_SIZE * 3 + batch_ind * 3 + 2]
            };
            if (sphere_sphere_self_collision(
                sphere_1[0], sphere_1[1], sphere_1[2], ffw_sg2_spheres_array[sphere_1_ind].w,
                sphere_2[0], sphere_2[1], sphere_2[2], ffw_sg2_spheres_array[j].w
            )){
                //return false;
                has_collision=true;
            }
        }
    }
    return !has_collision;

}

__device__ __forceinline__
bool ffw_sg2_self_collision_check_early(
    volatile float *sphere_pos,
    volatile int *joint_in_collision,
    const int tid,
    volatile unsigned int *motion_cc_flag
) {
    const int thread_ind = tid % 4;
    const int batch_ind  = tid / 4;

    for (
        int i = thread_ind;
        i < FFW_SG2_SELF_CC_RANGE_COUNT;
        i += 4
    ) {
        // block의 다른 waypoint에서 collision 확정
        if (motion_cc_should_stop(motion_cc_flag)) {
            return false;
        }

        const int sphere_1_ind =
            ffw_sg2_self_cc_ranges[i][0];

        if (
            joint_in_collision[
                FFW_SG2_JOINT_FLAG_STRIDE * batch_ind +
                ffw_sg2_sphere_to_joint[sphere_1_ind]
            ] == 0
        ) {
            continue;
        }

        const float sphere_1[3] = {
            sphere_pos[
                sphere_1_ind *
                FFW_SG2_BATCH_SIZE * 3 +
                batch_ind * 3 + 0
            ],
            sphere_pos[
                sphere_1_ind *
                FFW_SG2_BATCH_SIZE * 3 +
                batch_ind * 3 + 1
            ],
            sphere_pos[
                sphere_1_ind *
                FFW_SG2_BATCH_SIZE * 3 +
                batch_ind * 3 + 2
            ]
        };


        for (
            int j = ffw_sg2_self_cc_ranges[i][1];
            j <= ffw_sg2_self_cc_ranges[i][2];
            ++j
        ) {
            // 다른 thread가 그 사이 실제 collision을 찾았을 수도 있음
            if (motion_cc_should_stop(motion_cc_flag)) {
                return false;
            }

            const float sphere_2[3] = {
                sphere_pos[
                    j * FFW_SG2_BATCH_SIZE * 3 +
                    batch_ind * 3 + 0
                ],
                sphere_pos[
                    j * FFW_SG2_BATCH_SIZE * 3 +
                    batch_ind * 3 + 1
                ],
                sphere_pos[
                    j * FFW_SG2_BATCH_SIZE * 3 +
                    batch_ind * 3 + 2
                ]
            };

            if (
                sphere_sphere_self_collision(
                    sphere_1[0],
                    sphere_1[1],
                    sphere_1[2],
                    ffw_sg2_spheres_array[
                        sphere_1_ind
                    ].w,

                    sphere_2[0],
                    sphere_2[1],
                    sphere_2[2],
                    ffw_sg2_spheres_array[j].w
                )
            ) {
                motion_cc_report_collision(
                    motion_cc_flag
                );

                return false;
            }
        }
    }

    return true;
}

// 4 threads per discretized motion for env collision check
template <>
__device__ bool env_collision_check<ppln::robots::FfwSg2>(volatile float* sphere_pos, volatile int* joint_in_collision, ppln::collision::Environment<float> *env, const int tid){
    const int thread_ind = tid % 4;
    const int batch_ind = tid / 4;
    bool has_collision=false;

    for (int i = thread_ind; i < FFW_SG2_SPHERE_COUNT-FFW_SG2_SPHERE_COUNT%4; i += 4){
        // sphere i, robot batch_ind (16 robots)
        if (joint_in_collision[FFW_SG2_JOINT_FLAG_STRIDE * batch_ind + ffw_sg2_sphere_to_joint[i]] > 0 && 
            sphere_environment_in_collision(
                env,
                sphere_pos[i * FFW_SG2_BATCH_SIZE * 3 + batch_ind * 3 + 0],
                sphere_pos[i * FFW_SG2_BATCH_SIZE * 3 + batch_ind * 3 + 1],
                sphere_pos[i * FFW_SG2_BATCH_SIZE * 3 + batch_ind * 3 + 2],
                ffw_sg2_spheres_array[i].w
            )
        ) {
            //return false;
            has_collision=true;
        } 
        if (warp_any_full_mask(has_collision)) return false;
    }
    int i=FFW_SG2_SPHERE_COUNT-1-thread_ind;
    if (joint_in_collision[FFW_SG2_JOINT_FLAG_STRIDE * batch_ind + ffw_sg2_sphere_to_joint[i]] > 0 && 
        sphere_environment_in_collision(
            env,
            sphere_pos[i * FFW_SG2_BATCH_SIZE * 3 + batch_ind * 3 + 0],
            sphere_pos[i * FFW_SG2_BATCH_SIZE * 3 + batch_ind * 3 + 1],
            sphere_pos[i * FFW_SG2_BATCH_SIZE * 3 + batch_ind * 3 + 2],
            ffw_sg2_spheres_array[i].w
        )
    ) {
        return false;
    } 
    return true;
}

__device__ __forceinline__
bool ffw_sg2_env_collision_check_early(
    volatile float *sphere_pos,
    volatile int *joint_in_collision,
    ppln::collision::Environment<float> *env,
    const int tid,
    volatile unsigned int *motion_cc_flag
) {
    const int thread_ind = tid % 4;
    const int batch_ind  = tid / 4;

    // 기존 exact env collision과 같은 sphere 분배
    for (
        int i = thread_ind;
        i < FFW_SG2_SPHERE_COUNT - FFW_SG2_SPHERE_COUNT % 4;
        i += 4
    ) {
        // 다른 waypoint에서 이미 실제 collision 발견
        if (motion_cc_should_stop(motion_cc_flag)) {
            return false;
        }

        if (
            joint_in_collision[
                FFW_SG2_JOINT_FLAG_STRIDE * batch_ind +
                ffw_sg2_sphere_to_joint[i]
            ] > 0
            &&
            sphere_environment_in_collision(
                env,
                sphere_pos[
                    i * FFW_SG2_BATCH_SIZE * 3 +
                    batch_ind * 3 + 0
                ],
                sphere_pos[
                    i * FFW_SG2_BATCH_SIZE * 3 +
                    batch_ind * 3 + 1
                ],
                sphere_pos[
                    i * FFW_SG2_BATCH_SIZE * 3 +
                    batch_ind * 3 + 2
                ],
                ffw_sg2_spheres_array[i].w
            )
        ) {
            // 실제 collision 확정
            motion_cc_report_collision(
                motion_cc_flag
            );

            return false;
        }
    }


    // 기존 remainder sphere 처리
    const int i =
        FFW_SG2_SPHERE_COUNT - 1 - thread_ind;

    if (motion_cc_should_stop(motion_cc_flag)) {
        return false;
    }

    if (
        joint_in_collision[
            FFW_SG2_JOINT_FLAG_STRIDE * batch_ind +
            ffw_sg2_sphere_to_joint[i]
        ] > 0
        &&
        sphere_environment_in_collision(
            env,
            sphere_pos[
                i * FFW_SG2_BATCH_SIZE * 3 +
                batch_ind * 3 + 0
            ],
            sphere_pos[
                i * FFW_SG2_BATCH_SIZE * 3 +
                batch_ind * 3 + 1
            ],
            sphere_pos[
                i * FFW_SG2_BATCH_SIZE * 3 +
                batch_ind * 3 + 2
            ],
            ffw_sg2_spheres_array[i].w
        )
    ) {
        motion_cc_report_collision(
            motion_cc_flag
        );

        return false;
    }

    return true;
}
}
